import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';

/// An SVG glyph drawn in the ambient icon colour, so it follows the same
/// enabled, disabled and selected states as a Material [Icon].
class HubIcon extends StatelessWidget {
  final String svg;
  final double size;
  final Color? color;
  const HubIcon(this.svg, {super.key, this.size = 20, this.color});
  @override
  Widget build(BuildContext context) {
    final theme = IconTheme.of(context);
    final tint = color ?? theme.color ?? Colors.black;
    return SvgPicture.string(
      svg,
      width: size,
      height: size,
      excludeFromSemantics: true,
      colorFilter: ColorFilter.mode(
        tint.withValues(alpha: tint.a * (theme.opacity ?? 1)),
        BlendMode.srcIn,
      ),
    );
  }
}

